CREATE TABLE public.portal_odres_listas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, criado_por uuid NOT NULL, nome_arquivo text NOT NULL, total_esperado integer NOT NULL CHECK(total_esperado BETWEEN 1 AND 200000), ativo boolean NOT NULL DEFAULT false, criado_em timestamptz NOT NULL DEFAULT now(), publicado_em timestamptz);
GRANT SELECT ON public.portal_odres_listas TO authenticated;
GRANT ALL ON public.portal_odres_listas TO service_role;
ALTER TABLE public.portal_odres_listas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.portal_odres_cpfs (lista_id uuid NOT NULL REFERENCES public.portal_odres_listas(id) ON DELETE CASCADE, cpf text NOT NULL CHECK(cpf ~ '^[0-9]{11}$'), PRIMARY KEY(lista_id,cpf));
GRANT ALL ON public.portal_odres_cpfs TO service_role;
ALTER TABLE public.portal_odres_cpfs ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX portal_odres_lista_vigente ON public.portal_odres_listas(tenant_id) WHERE ativo;
CREATE INDEX portal_odres_lista_historico ON public.portal_odres_listas(tenant_id,criado_em DESC);
CREATE FUNCTION public.portal_odres_pode_importar() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.user_id=auth.uid() AND m.tenant_id='00000000-0000-0000-0000-000000000001') AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.user_permissions p WHERE p.user_id=auth.uid() AND '/admin/importar-devedores'=ANY(p.abas_permitidas))) $$;
REVOKE ALL ON FUNCTION public.portal_odres_pode_importar() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.portal_odres_pode_importar() TO authenticated,service_role;
CREATE POLICY portal_odres_listas_leitura ON public.portal_odres_listas FOR SELECT TO authenticated USING (tenant_id='00000000-0000-0000-0000-000000000001' AND public.portal_odres_pode_importar());
CREATE FUNCTION public.portal_odres_cpf_valido(p_cpf text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE n integer; i integer; soma integer; digito integer; BEGIN IF p_cpf IS NULL OR p_cpf !~ '^[0-9]{11}$' OR p_cpf ~ '^([0-9])\1{10}$' THEN RETURN false; END IF; FOR n IN 9..10 LOOP soma:=0; FOR i IN 1..n LOOP soma:=soma+substring(p_cpf,i,1)::integer*(n+2-i); END LOOP; digito:=(soma*10)%11; IF digito=10 THEN digito:=0; END IF; IF digito<>substring(p_cpf,n+1,1)::integer THEN RETURN false; END IF; END LOOP; RETURN true; END $$;
CREATE FUNCTION public.portal_odres_iniciar(p_arquivo text,p_total integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF NOT public.portal_odres_pode_importar() THEN RAISE EXCEPTION 'Sem permissão para importar'; END IF; IF length(trim(coalesce(p_arquivo,'')))=0 OR length(p_arquivo)>255 THEN RAISE EXCEPTION 'Arquivo inválido'; END IF; INSERT INTO public.portal_odres_listas(tenant_id,criado_por,nome_arquivo,total_esperado) VALUES('00000000-0000-0000-0000-000000000001',auth.uid(),p_arquivo,p_total) RETURNING id INTO v_id; RETURN v_id; END $$;
CREATE FUNCTION public.portal_odres_adicionar_lote(p_lista uuid,p_cpfs text[]) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_count integer; v_lista public.portal_odres_listas; BEGIN IF NOT public.portal_odres_pode_importar() THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO v_lista FROM public.portal_odres_listas WHERE id=p_lista AND criado_por=auth.uid() AND tenant_id='00000000-0000-0000-0000-000000000001' FOR UPDATE; IF NOT FOUND OR v_lista.publicado_em IS NOT NULL THEN RAISE EXCEPTION 'Lista indisponível'; END IF; IF coalesce(cardinality(p_cpfs),0) NOT BETWEEN 1 AND 1000 OR EXISTS(SELECT 1 FROM unnest(p_cpfs) c WHERE NOT public.portal_odres_cpf_valido(c)) THEN RAISE EXCEPTION 'Lote inválido'; END IF; INSERT INTO public.portal_odres_cpfs(lista_id,cpf) SELECT p_lista,c FROM unnest(p_cpfs) c ON CONFLICT DO NOTHING; SELECT count(*) INTO v_count FROM public.portal_odres_cpfs WHERE lista_id=p_lista; IF v_count>v_lista.total_esperado THEN RAISE EXCEPTION 'Total excedido'; END IF; RETURN v_count; END $$;
CREATE FUNCTION public.portal_odres_publicar(p_lista uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_lista public.portal_odres_listas; v_count integer; BEGIN IF NOT public.portal_odres_pode_importar() THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM pg_advisory_xact_lock(hashtext('portal_odres_lista_vigente')); SELECT * INTO v_lista FROM public.portal_odres_listas WHERE id=p_lista AND criado_por=auth.uid() AND tenant_id='00000000-0000-0000-0000-000000000001' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lista indisponível'; END IF; IF v_lista.ativo THEN RETURN v_lista.total_esperado; END IF; IF v_lista.publicado_em IS NOT NULL OR EXISTS(SELECT 1 FROM public.portal_odres_listas WHERE tenant_id=v_lista.tenant_id AND ativo AND criado_em>v_lista.criado_em) THEN RAISE EXCEPTION 'Lista substituída por importação mais recente'; END IF; SELECT count(*) INTO v_count FROM public.portal_odres_cpfs WHERE lista_id=p_lista; IF v_count<>v_lista.total_esperado OR v_count=0 THEN RAISE EXCEPTION 'Lista incompleta'; END IF; UPDATE public.portal_odres_listas SET ativo=false WHERE tenant_id=v_lista.tenant_id AND ativo; UPDATE public.portal_odres_listas SET ativo=true,publicado_em=now() WHERE id=p_lista; DELETE FROM public.portal_odres_cpfs c USING public.portal_odres_listas l WHERE c.lista_id=l.id AND l.tenant_id=v_lista.tenant_id AND l.id<>p_lista AND (l.publicado_em IS NOT NULL OR l.criado_em<now()-interval '7 days'); RETURN v_count; END $$;
REVOKE ALL ON FUNCTION public.portal_odres_iniciar(text,integer),public.portal_odres_adicionar_lote(uuid,text[]),public.portal_odres_publicar(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.portal_odres_iniciar(text,integer),public.portal_odres_adicionar_lote(uuid,text[]),public.portal_odres_publicar(uuid) TO authenticated;
CREATE FUNCTION public.portal_odres_identificado(p_cpf text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.portal_odres_listas l JOIN public.portal_odres_cpfs c ON c.lista_id=l.id WHERE l.tenant_id='00000000-0000-0000-0000-000000000001' AND l.ativo AND c.cpf=p_cpf) $$;
REVOKE ALL ON FUNCTION public.portal_odres_identificado(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.portal_odres_identificado(text) TO service_role;
REVOKE ALL ON FUNCTION public.portal_odres_cpf_valido(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.portal_odres_cpf_valido(text) TO authenticated,service_role;